type Seed = { id: number; shortTitle: string; formalTitle: string; overview: string; thesis?: string; moves: Array<{ title: string; body: string }>; closer: Array<{ title: string; body: string }>; distinction: [string, string, string, string, string]; misreading: string; reflection: string; audit: string[]; nodes: string[]; model: VisualModel };
const makeChapter = (seed: Seed): Chapter => ({
  id: seed.id, shortTitle: seed.shortTitle, formalTitle: seed.formalTitle, overview: seed.overview,
  reflection: seed.reflection, relatedNodes: seed.nodes, visualModel: seed.model,
  deep: { thesis: seed.thesis ?? seed.moves[0].body, context: seed.overview, moves: seed.moves, closeReading: seed.closer,
    distinction: { title: seed.distinction[0], firstLabel: seed.distinction[1], first: seed.distinction[2], secondLabel: seed.distinction[3], second: seed.distinction[4] },
    misreading: seed.misreading, observation: seed.reflection, selfAudit: seed.audit,
    sourceAnchor: `Book 35, ${seed.id <= 4 ? "Part One, on unity" : "Part Two, on trust"}, ${seed.formalTitle}.` },
});
const chain = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({ kind: "chain", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })) });
const pair = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({ kind: "pair", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })) });
const spectrum = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({ kind: "spectrum", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })) });

const book35Base: Chapter[] = [
  makeChapter({
    id: 1, shortTitle: "Why trust is praised", formalTitle: "The excellence of trust",
    overview: "Ghazali opens with what the Quran and the Prophet say about trusting God. He also warns that trust is hard to understand and hard to do, which is why the book first explains what trust is built on.",
    thesis: "Trust in God is praised very highly — but it is easy to get wrong in two opposite directions, so Ghazali first sets out the belief it rests on.",
    moves: [
      { title: "The Quran's promise", body: "The Quran says, “Whoever puts their trust in God, He is enough for them,” and “God loves those who trust Him.” Ghazali says there is no higher honour than being loved by God and looked after by Him. And it asks, “Is God not enough for His servant?” Someone who looks for what is “enough” anywhere else, he says, is acting as if they didn't believe that verse." },
      { title: "The seventy thousand", body: "The Prophet described seventy thousand people of his community who will enter Paradise without any reckoning. They are the ones who don't use branding as a cure, don't read bad omens, don't ask others to recite charms over them, “and who trust in their Lord.” A Companion named Ukkasha asked him to pray that he would be one of them, and the Prophet did. When another man asked the same, the Prophet said, “Ukkasha got there before you.”" },
      { title: "Like the birds", body: "The Prophet said, “If you trusted God as He should be trusted, He would provide for you as He provides for the birds. They go out hungry in the morning and come back full in the evening.” Notice the birds still fly out. And he said, “Whoever wants to be the richest of people should trust what is with God more than what is in their own hands.”" },
      { title: "Abraham in the catapult", body: "When Abraham was about to be thrown into the fire, the angel Gabriel came to him and asked, “Do you need anything?” Abraham said, “From you? No.” He had already said, “God is enough for me, and He is the best one to rely on.” Ghazali says that is why the Quran praises “Abraham, who kept his word.”" },
      { title: "Two ways to get it wrong", body: "Ghazali admits that trust is hard to understand. If you rely on causes — money, doctors, plans — as if they had power by themselves, you damage your belief in God's oneness. But if you ignore causes completely, you go against the Prophet's example and the religious law. Finding the balance between the two is, he says, extremely difficult." },
      { title: "Knowledge, state, action", body: "Like every quality of faith, trust has three parts: a knowledge, which is its root; a state of the heart, which is trust itself; and actions, which are its fruit. The knowledge is what we mean when we say, “There is no god but God, alone, without partner. His is the kingdom and His is the praise, and He has power over all things.” So the first half of the book explains that knowledge, and the second half explains the state and the actions." },
      { title: "When the words become real", body: "Anyone can say those words. Ghazali says the foundation of trust is in place when their meaning becomes a lasting quality of the heart that takes it over. That is a high bar, and it explains why many people hold the right belief and still have very little trust." },
    ],
    closer: [
      { title: "The hand that wasn't stung", body: "Sa'id ibn Jubayr was stung by a scorpion. His mother made him promise to let someone recite a charm over it. He kept his promise — but held out the hand that hadn't been stung. He kept his word to his mother, and kept his trust in God too." },
      { title: "Don't let the promise make you lazy", body: "A scholar said: “Don't let the provision that is guaranteed to you distract you from the work that is required of you.” Trust is not an excuse to stop working, as the rest of the book will show." },
    ],
    distinction: ["Two ways to approach trust", "Through what you believe", "Understanding who God is, which produces trust in the heart.", "Through pep talks", "Being told to “just trust more”, which the book's structure deliberately avoids."],
    misreading: "Don't read the praise of trust as a call to give up working or planning. The whole second half of the book shows that it isn't.",
    reflection: "Before asking why you don't trust God more, ask what you actually believe about Him.",
    audit: ["What do I really believe about God, in practice?", "Is that belief part of my heart, or just a phrase?", "Where does my worry contradict what I say?", "Do I lean too much on causes, or pretend they don't matter?"],
    nodes: ["tawakkul", "tawhid"],
    model: chain("The book's structure", "The order is the argument.", [["Unity", "The knowledge that is the root, treated in Part One.", "support"], ["The state", "Reliance, which follows the knowledge rather than being summoned.", "balance"], ["The acts", "What those who trust actually do, which is most of Part Two.", "support"]]),
  }),
  makeChapter({
    id: 2, shortTitle: "Four levels, one walnut", formalTitle: "The reality of the unity that is the root of trust",
    overview: "This is the most famous passage in the book. Ghazali describes four levels of believing in God's oneness, using a walnut: two shells, a kernel, and the oil inside the kernel.",
    thesis: "Belief in God's oneness has four levels, from words on the tongue to seeing only God — and trust is built on the third.",
    moves: [
      { title: "The walnut", body: "A walnut has an outer shell, an inner shell, a kernel, and oil inside the kernel. Ghazali says belief in God's oneness is like that. There is a shell, a shell inside the shell, a kernel, and the kernel of the kernel. These aren't four opinions to choose between. They are four depths of the same thing." },
      { title: "Level one: only the tongue", body: "The first level is saying “There is no god but God” with your tongue while your heart ignores it or denies it. That is the belief of a hypocrite. It protects a person in this world, because no one can cut open hearts. But it is like a walnut's outer green shell: bitter to eat, ugly inside, and if you burn it, it puts the fire out and makes smoke. It is only useful for a while, to protect the inner shell." },
      { title: "Level two: the heart agrees", body: "The second level is when the heart accepts the meaning of the words, as ordinary Muslims do. Ghazali calls it a knot tied on the heart. It is real and valuable: it protects its owner in the next life, if they die holding it and sins haven't loosened it. It is like the walnut's hard inner shell, which keeps the kernel safe and can even be used as firewood." },
      { title: "Level three: seeing it", body: "The third level is seeing it directly, by a light from God. You see many things, but you see them all as coming from the One. This is the level of those brought near to God. It is the kernel. And Ghazali says trust is built on this level: the realisation that there is no real doer except God." },
      { title: "Level four: seeing only One", body: "The fourth level is seeing nothing in existence but the One. This is the level of the truthful. Sufis call it “passing away”, because someone who sees only One doesn't even notice themselves. It is the oil inside the kernel. Ghazali won't explain it further, and says trust doesn't depend on it." },
      { title: "How can many things be one?", body: "How can someone see only one thing when they see sky, earth and people? Ghazali gives a hint. A person has a body, limbs, veins, bones and organs — many parts. But we also say “one person”. Someone looking lovingly at a friend doesn't think about their bones and veins. In the same way, the whole of existence can be seen as many or as one, depending on how you look." },
      { title: "Where theologians stand", body: "Ghazali adds a sharp point about theologians. People with false beliefs try to loosen the knot of level two in ordinary hearts. Theologians defend the knot. But he says a theologian's belief isn't deeper than an ordinary person's. Their skill is in arguments that protect the knot, not in seeing more of the walnut." },
    ],
    closer: [
      { title: "Stuck on level three", body: "Al-Hallaj once saw Ibrahim al-Khawwas travelling through the desert and asked what he was doing. Khawwas said he was travelling to perfect his trust in God. Hallaj said, “You've spent your life building up your inner self. Where is losing yourself in God's oneness?” Ghazali explains that Khawwas was working on the third level, and Hallaj was asking about the fourth." },
      { title: "Believe in what you haven't reached", body: "Even if you haven't reached the higher levels, Ghazali says, don't deny them. Believe in them. Just as you can believe in prophethood without being a prophet, and have a share in it through your belief, you have a share in this oneness by believing in it." },
    ],
    distinction: ["Two things both called belief in oneness", "A knot on the heart", "The heart accepts and holds on to the meaning — real, and what most people have.", "Seeing it", "Everything is seen as coming from the One — a different level, not just a firmer knot."],
    misreading: "Don't think the higher levels make the lower ones worthless. Ghazali says exactly what each level gives, and the second level is what protects a person in the next life.",
    reflection: "Place yourself honestly on the four levels. Most readers are on the second, and Ghazali doesn't treat that as failure.",
    audit: ["Which level is really mine?", "Is my belief a firm knot or a careless phrase?", "Have I confused arguing well with believing deeply?", "What would the third level change in a hard moment?"],
    nodes: ["tawhid", "four-degrees"],
    model: spectrum("The walnut", "Each layer is real, and each secures something different.", [["Outer shell", "The tongue alone; the unity of the hypocrites.", "warning"], ["Inner shell", "The heart's assent; a knot without expansion, and what most people have.", "balance"], ["The kernel", "Many things seen as issuing from One; the station of the near.", "support"], ["The oil", "Only one seen at all, so the seer is not seen either.", "support"]]),
  }),
  makeChapter({
    id: 3, shortTitle: "His is the kingdom", formalTitle: "Belief in the power that trust rests on",
    overview: "Trust rests on seeing that God is the only real doer of everything. Ghazali shows the two things that trick people into thinking otherwise — and tells a famous story of a traveller asking the paper, the ink and the pen who is to blame.",
    thesis: "Every cause, from the wind to a human hand, is moved by God — seeing that is what lets the heart rely on Him alone.",
    moves: [
      { title: "No doer but God", body: "The heart of level three is seeing that there is no real doer except God. Creation, provision, giving, withholding, life, death, wealth and poverty — God alone brings them about. Everything else is moved, not a mover. When you see this, your fear, hope and trust all turn to Him. Ghazali says the devil tries to block this view in two ways." },
      { title: "Trap one: things", body: "The first trap is relying on lifeless things: counting on rain to grow crops, clouds to bring rain, or wind to move a ship. The Quran describes people who pray sincerely when their ship is in danger, and then, once safe on land, give the credit to something else. One explanation is that they say, “If the wind hadn't been right, we wouldn't have made it.”" },
      { title: "The pardon and the pen", body: "Ghazali's picture: a man is about to be executed. The king writes a letter pardoning him. The man starts praising the ink, the paper and the pen: “If it weren't for the pen, I'd be dead!” That would be foolish. The pen has no power of its own. It is moved by the writer's hand. The sun, the rain, the clouds — everything is like a pen in the hand of God's power." },
      { title: "Trap two: people's choices", body: "Once that trap fails, the devil tries the second one, which is harder: “Fine, the pen is moved. But what about the person holding it? That man gives you food if he wants, or strikes you if he wants. How can you not fear him or hope in him?” Ghazali says most people slip here." },
      { title: "The ant on the page", body: "People who stop at the writer, he says, are like an ant crawling on paper. It sees the pen's tip turning the page black and thinks the pen is doing it. Its eyes are too small to see the hand, let alone the person. Someone whose heart hasn't been opened by God's light can see only as far as the human being, and stops there." },
      { title: "The traveller who asked everyone", body: "Ghazali tells a story. A traveller sees paper blackened with ink and asks it why. The paper says, “Ask the ink.” The ink says, “The pen snatched me from my inkpot.” The pen says, “Ask the hand — it cut me from the riverbank and drags me along.” The hand says, “I'm just flesh. Ask the power that rides me.” Power blames will. Will blames the mind's judgement. And so on, until the traveller reaches the point where he can only say: God does as He wills, and is not questioned." },
      { title: "The magicians and the calf", body: "Ghazali adds why deep conviction lasts. Pharaoh's magicians knew magic inside out, so when they saw Moses' staff, they knew it was beyond magic. Even under threat of death, they didn't waver. But some of Moses' people had believed only because they saw the staff become a snake. When they saw a golden calf that made a sound, they fell for it. Faith that rests on what you see can be swapped for something else you see." },
    ],
    closer: [
      { title: "The ruler and the executioner", body: "If God does everything, how can people be said to act? Ghazali says “doing” has two meanings. We say the ruler put someone to death, and we say the executioner did — both are true, in different senses. God does things as the Creator. A person does them as the one in whom God created the knowledge, will and ability. That is why the Quran says, “You did not throw when you threw, but God threw.”" },
      { title: "Chosen, and yet compelled", body: "Ghazali adds a hard thought. When a needle comes at your eye, you blink — you can't not blink, even though blinking is something you “want”. Choosing is the same, only slower: the mind decides what is best, the will follows, the hand moves. So a person is, in his words, “compelled to choose”. For people who find this too deep, he says, a simpler reason is enough: a house with two masters falls apart, so the world has one Lord." },
    ],
    distinction: ["Two ways to thank for a pardon", "Thanking the pen", "Giving credit to the cause you can see — the wind, the medicine, the person.", "Thanking the king", "Seeing the cause as a pen in God's hand, and turning your thanks and trust to Him."],
    misreading: "Don't read this as saying causes are fake or that people aren't responsible for what they do. Ghazali says people really act, in their sense of acting — he is correcting where the heart puts its trust.",
    reflection: "Think of something that went well recently. Notice whom or what you instinctively credited — and whether it was the pen or the writer.",
    audit: ["Which “pen” do I trust most?", "Whose choices do I fear as if they had power of their own?", "Does my faith rest on what I see, or on what I understand?", "Where am I the ant on the page?"],
    nodes: ["tawakkul", "power", "causes"],
    model: pair("What the belief covers", "The distinction keeps reliance from becoming forecasting.", [["What is possible", "Including causes not in view, which is the belief required.", "support"], ["What is likely", "A prediction about outcomes, which is a different thing entirely.", "warning"]]),
  }),
  makeChapter({
    id: 4, shortTitle: "His is the praise", formalTitle: "Belief in the generosity and wisdom that trust rests on",
    overview: "Knowing God can do everything isn't enough to rely on Him. You also need to trust that what He does is wise and generous. Ghazali states this belief very strongly — and stops where it touches the mystery of fate.",
    thesis: "Trust also needs certainty that God's arrangement of the world is wise, fair and generous — that nothing better was possible — even where we can't see why.",
    moves: [
      { title: "Power isn't enough", body: "You can believe someone has the power to help you and still not rely on them, if you doubt they care. Ghazali says belief in God's oneness makes you look to the Causer of causes. Belief in His mercy is what makes you feel safe with Him. Trust needs both: confidence in the One you rely on, and a heart at peace that He will take good care." },
      { title: "If everyone were a genius", body: "Ghazali asks the reader to be certain of this. Imagine God made every person as intelligent as the most intelligent person, and as knowledgeable as the most knowledgeable, and then doubled it. Imagine He showed them how everything ends, and let them run the universe together. They couldn't improve God's arrangement by the wing of a gnat, or remove any illness, lack or poverty from anyone it was right for." },
      { title: "Nothing better was possible", body: "So everything God shares out — provision, lifespan, joy, sadness, weakness, strength — is fair and right, arranged as it should be. Ghazali says that if something better had been possible and God had held it back, that would be stinginess, which goes against His generosity. And if He couldn't do it, that would be weakness, which goes against His being God." },
      { title: "Loss here, gain there", body: "How can poverty or pain be good? Ghazali says every hardship in this world is a loss in this world and a gain in the next. And contrast shows value. Without night, no one would know what day is worth. Without illness, the healthy wouldn't enjoy their health. The Quran says that if you look again and again at creation, you won't find a flaw." },
      { title: "The hand that is cut off", body: "He gives a picture. When a hand is badly infected, a doctor may cut it off to save the person's life. That isn't cruel. It is choosing the greater good over the lesser. Ghazali says the differences between people in this life and the next follow a similar wisdom — even when we can't trace it." },
      { title: "Where Ghazali stops", body: "Ghazali says this is a second ocean, almost as deep as the ocean of God's oneness, and many have drowned in it. Beyond it lies the secret of fate, which those who know are forbidden to reveal. So he gives only the core: whatever reaches you could not have missed you, and whatever missed you could not have reached you." },
    ],
    closer: [
      { title: "Abu Yazid's answer", body: "Someone told Abu Yazid al-Bistami that trust means lions and snakes on either side of you wouldn't disturb your heart. He said, “That's close. But if the people of Paradise were enjoying it and the people of Hell were suffering in it, and you felt any objection to how it was arranged, you would have left trust altogether.” Ghazali says this is the deepest knowledge of God's wisdom." },
      { title: "Naming a limit honestly", body: "Ghazali includes this belief even though he can't fully explain it, because trust really needs it. Leaving it out would mean resting trust on power alone. Saying “this is where my explanation stops” is different from pretending there's no limit." },
    ],
    distinction: ["Two beliefs about the same power", "Used with wisdom and care", "What God does is done well — which makes it possible to rely on Him.", "Used carelessly", "Power without care — which produces fear, not trust."],
    misreading: "Don't read this as saying every hardship can be neatly explained, or that you shouldn't care about suffering. Ghazali says there is wisdom in it, and admits where our understanding stops.",
    reflection: "Notice whether your struggle to trust is about whether God can, or whether He cares. They are different problems.",
    audit: ["Do I doubt God's power, or His care?", "What in my life makes the second one hard?", "Am I demanding an explanation before I will trust?", "Can I see any good that came from a past loss?"],
    nodes: ["tawhid", "wisdom", "decree"],
    model: chain("Why three components", "Reliance fails if any one of them is missing.", [["One", "There is a single agent behind what occurs.", "support"], ["Able", "Nothing relied upon exceeds what can be done.", "support"], ["Wise and generous", "The ability is exercised with care, which is what makes reliance rather than fear.", "support"]]),
  }),
  makeChapter({
    id: 5, shortTitle: "The lawyer", formalTitle: "The definition of trust",
    overview: "The second half of the book begins by defining trust itself. Ghazali uses the picture of hiring a lawyer to defend you, and shows what you must believe about someone to really rely on them.",
    thesis: "Trust is the heart relying on the One it has handed its affairs to — which needs belief in His knowledge, power and care, and also a heart strong enough to be calm.",
    moves: [
      { title: "Where the word comes from", body: "The Arabic word for trust, tawakkul, comes from the word for appointing someone to act for you. To entrust something to someone means handing it over and relying on them. You are only really relying on them if you feel at ease, and don't suspect them of letting you down. So trust is the heart relying only on the one it has entrusted." },
      { title: "The lawyer in court", body: "Imagine someone is falsely accused through a clever trick, and hires a lawyer to expose it. They will only be at peace if they believe four things. The lawyer knows exactly where the trick lies. The lawyer has the nerve to say the truth openly, without being put off by flattery, fear or embarrassment. The lawyer can explain it well. And the lawyer cares enough to give it everything." },
      { title: "If one is missing", body: "If the client doubts any one of those four, or thinks the other side's lawyer is better, they won't be calm. Their heart stays restless, busy with their own schemes to make up for what their lawyer might lack. That restless scheming is the sign that trust is missing." },
      { title: "Now apply it to God", body: "Suppose you truly believe there is no doer but God. You believe His knowledge and power are complete, and His care and mercy for you are complete, with nothing beyond them. Then your heart will rely on Him alone — not on anything else, and not on your own strength. That is what “There is no power and no strength except through God” means." },
      { title: "A second cause of failure: a timid heart", body: "But sometimes trust is missing even when the belief is there. Ghazali says the heart can be shaken by imagination. If someone offers you honey that looks like something disgusting, you may not be able to eat it, even though you know it's honey. Most people wouldn't sleep in a room next to a dead body, even though they know for certain it can't move. That is timidity of the heart, not a lack of knowledge." },
      { title: "Certainty and calm are different", body: "So trust needs two things: strong certainty and a strong heart. Abraham believed God gives life to the dead, yet asked to see it, “so that my heart may be at rest.” Certainty is one thing and a calm heart is another. Some people are certain but not calm. And some people are calm without any real certainty at all." },
      { title: "When the lawyer is your father", body: "The strength of trust goes up and down with how strongly you believe in those qualities. Ghazali notes that if the lawyer were your own father, who would do anything for you, you would be completely sure of his care. That one quality would be beyond doubt. Trust in God grows the same way, as each belief becomes certain." },
    ],
    closer: [
      { title: "What the picture does", body: "The lawyer picture turns a feeling you can only claim into beliefs you can check. If you aren't at peace, you can ask: do I doubt He knows? Do I doubt He can? Do I doubt He cares? Or is it just a timid heart? Telling someone to “trust more” can't do that." },
      { title: "A warning from the Torah", body: "Ghazali quotes a saying reported from the Torah: “Cursed is the one whose trust is in a human being like himself.” And a report from the Prophet: “Whoever seeks strength through people, God will humble.”" },
    ],
    distinction: ["Two people with a lawyer", "At peace", "They trust all four qualities, so they aren't busy with their own backup plans.", "Scheming", "They doubt one quality, and it shows as restless planning rather than as a stated doubt."],
    misreading: "Don't read the lawyer picture as turning faith into a legal deal. It is there to help you find exactly which belief is missing — or whether it's your heart, not your belief, that needs strengthening.",
    reflection: "Take the thing you worry about most. Ask whether you doubt God's knowledge, power or care — or whether your heart is just timid.",
    audit: ["Which of the qualities would I hesitate over?", "Is my worry about knowledge, power, care — or nerves?", "What backup plan is my heart really relying on?", "Where am I certain but still not calm?"],
    nodes: ["tawakkul", "four-conditions"],
    model: chain("The advocate's four conditions", "Doubting any one keeps the heart busy trying to compensate.", [["Guidance", "He knows where the deception lies, and nothing subtle escapes him.", "support"], ["Power", "He dares state the truth without flattery, fear, shame, or cowardice.", "support"], ["Expression", "He can put into words whatever his heart has grasped.", "support"], ["Compassion", "He will actually spend everything he can on the matter.", "support"]]),
  }),
  makeChapter({
    id: 6, shortTitle: "Three levels of trust", formalTitle: "The degrees of trust",
    overview: "Trust isn't all or nothing. Ghazali describes three levels with three pictures: a client with a lawyer, a small child with its mother, and a body in the hands of the person washing it. He also says what planning is still left at each.",
    thesis: "Trust comes in three levels — the client, the child and the washed body — and the first, which still plans and acts, is real trust.",
    moves: [
      { title: "Level one: the client", body: "At the first level, you trust God the way a client trusts a good lawyer. You are at peace, but you still do what a client does. Ghazali says this level still involves planning and choosing, but it drops some kinds of planning — the kind that goes around the lawyer." },
      { title: "What the client still does", body: "If the lawyer says, “I'll only speak if you come to court,” the client comes to court. If the client knows the lawyer always needs the documents, the client brings them. That isn't a lack of trust. It is part of trusting — doing what the one you rely on has told you to do. Only after coming and bringing the papers does the client sit back and wait calmly." },
      { title: "Level two: the child", body: "At the second level, you are like a small child with its mother. The child knows no one but her and runs to no one else. When something frightens it, the first word out of its mouth is “Mum!” Ghazali says this person trusts without even noticing they are trusting. Their heart is on the One they rely on, not on their own trust. They still plan in one way only: crying out to God in prayer." },
      { title: "Level three: the body being washed", body: "At the highest level, you are before God like a dead body in the hands of the person washing it. You see yourself moved entirely by God's power. You aren't even like the child who cries out and runs after its mother. You're like a child who knows its mother will come and feed it without being asked. Ghazali says this level can even lead a person to stop asking, out of trust that God gives before being asked." },
      { title: "How long each lasts", body: "Are these real? Yes, Ghazali says, but rare — the second and third very rare. And the higher they are, the less they last. He compares them to kinds of paleness in the face. The third is like the paleness of sudden fright, which passes quickly. The second is like the paleness of a fever, which may last a day or two. The first is like the paleness of a long illness, which may stay for a long time." },
      { title: "Sahl's answer", body: "Someone asked Sahl al-Tustari about the lowest level of trust. He said, “Giving up wishful thinking.” The middle? “Giving up choosing for yourself” — the second level. The highest? He wouldn't describe it. “Only someone who has reached the middle knows it.”" },
      { title: "“No power and no strength except through God”", body: "Ghazali says this saying captures trust. “Power” means the ability to move, and “strength” means the ability to act. The lawyer can make your efforts useful, but didn't create them. Only God both creates your power and strength and makes them useful. That is why the Prophet promised such a great reward for saying these words with understanding." },
    ],
    closer: [
      { title: "Why the first level matters most", body: "Most readers will spend their lives at the first level, and Ghazali counts it as real trust. The mistake is thinking trust means dropping all planning and effort. The right planning — doing what God has told you, in the way He has made things work — is part of trusting Him." },
      { title: "The child isn't passive", body: "The picture for the second level is chosen with care. The child isn't lying still. It cries, reaches out and holds on to its mother. What it doesn't do is sit and worry about whether she'll come." },
    ],
    distinction: ["Two ways to read clashing definitions of trust", "As levels", "Each speaker describes the level they are at, so the definitions fit together.", "As contradictions", "Only one can be right — which forces you to choose and misreads them all."],
    misreading: "Don't measure yourself against the third level. Ghazali says it is very rare and doesn't last. The first level, with its planning and effort, is real trust.",
    reflection: "Place yourself on the three levels, and remember the first is a real one — where the book expects most readers to be.",
    audit: ["Which level describes me?", "Am I comparing myself to the third?", "Do I do what God has told me, then wait calmly?", "What would crying out like the child look like for me this week?"],
    nodes: ["tawakkul", "three-stations"],
    model: spectrum("Three stations of trust", "Each is real, and the highest is rare.", [["The client", "At rest with the agent while continuing to act as a client acts.", "support"], ["The child", "Knows nothing but her, and does not deliberate about arrangements.", "support"], ["The washed", "Moved without any motion of one's own, which Ghazali marks as rare.", "balance"]]),
  }),
  makeChapter({
    id: 7, shortTitle: "What the masters meant", formalTitle: "What the masters said about the states of trust",
    overview: "Earlier spiritual teachers gave very different definitions of trust. Ghazali collects them and shows that each describes a different level or part of trust, rather than disagreeing.",
    thesis: "The teachers' definitions don't contradict each other — each describes the level the speaker was at, or one part of trust.",
    moves: [
      { title: "Why the definitions differ", body: "Ghazali says each teacher spoke about their own level and reported what trust meant for them. That was the habit of the Sufis. So instead of choosing between them, he matches each saying to the part of trust it describes." },
      { title: "Dhul-Nun", body: "Dhul-Nun al-Misri said trust is “throwing off the lords and cutting off the causes.” Ghazali says “throwing off the lords” points to belief in God's oneness, and “cutting off the causes” points to action. Asked for more, Dhul-Nun said, “Placing yourself in servanthood and taking yourself out of lordship” — which Ghazali reads as giving up the idea that you have power of your own." },
      { title: "Hamdun's debt", body: "Hamdun al-Qassar said: “If you had ten thousand coins and owed one tiny coin, you still wouldn't feel safe from dying with that debt on your neck. And if you owed ten thousand, with nothing to pay it, you wouldn't give up hope that God would pay it for you.” Ghazali says this points to belief in how wide God's power is, and that there are hidden causes besides the ones we can see." },
      { title: "Abraham and Gabriel again", body: "Abu Abd Allah al-Qurashi said trust is “holding on to God in every state,” which fits all three levels. Asked for more, he said, “Leaving every cause that leads to another cause.” Ghazali says that describes the third level — like Abraham telling Gabriel, “From you? No.” Asking Gabriel would have been a cause leading to a cause. Abraham left it, knowing that if God wanted, He would send Gabriel Himself." },
      { title: "Movement and stillness", body: "Abu Sa'id al-Kharraz said trust is “movement without stillness and stillness without movement.” Ghazali thinks this describes the second level. The stillness is the heart at rest with God. The movement is crying out to Him — like a child reaching for its mother while completely sure of her love." },
      { title: "Three steps", body: "Abu Ali al-Daqqaq said there are three steps: trust, then surrender, then handing everything over. The one who trusts is at peace with God's promise. The one who surrenders is content with God's knowledge. The one who hands everything over is pleased with God's decision. Ghazali says each is a different thing the heart focuses on." },
      { title: "Abu Bakr blocked the holes", body: "Some thought trust means not protecting yourself from snakes. But when the Prophet and Abu Bakr hid in the cave, Abu Bakr blocked the snake holes. Ghazali says trust is lost when your heart shifts to relying on yourself, not when your hand moves. And the proper fear is of the One who controls snakes, since snakes have no power except through God." },
    ],
    closer: [
      { title: "Why sort, not judge", body: "This is Ghazali's usual method with an old disagreement. What looks like a quarrel turns out to be several true descriptions of different things. The answer is sorting them, not declaring a winner." },
      { title: "Showing beats quoting", body: "Ghazali says there are many more sayings about trust, but he won't pile them up. “Understanding it for yourself is more useful than collecting quotations.”" },
    ],
    distinction: ["Two ways to read an extreme saying", "As a level", "It reports the speaker's own level, and doesn't bind people at other levels.", "As the definition", "It tells everyone what trust is — which would make almost everyone fail."],
    misreading: "Don't take the most extreme saying as the standard for everyone. Ghazali's whole treatment of these sayings is meant to stop that.",
    reflection: "Find the definition of trust you have been carrying around, and ask which level it came from.",
    audit: ["Whose definition of trust have I adopted?", "What level was that person at?", "Have I been failing a test meant for someone else?", "What does the first level actually ask of me?"],
    nodes: ["tawakkul", "three-stations", "means"],
    model: pair("Why the definitions differ", "Each reports a station rather than contesting the others.", [["Compatible", "Assigned to degrees, the accounts fit together and none is discarded.", "support"], ["Contradictory", "Read as rival definitions, they force a choice that misreads all of them.", "warning"]]),
  }),
  makeChapter({
    id: 8, shortTitle: "Trust and working", formalTitle: "The acts of those who trust",
    overview: "Does trusting God mean not working? Ghazali calls that the idea of ignorant people. He sorts every action by its purpose and every cause by how reliable it is, and shows where trust fits in.",
    thesis: "Trust doesn't mean giving up work: using sure and likely causes is fine, only far-fetched scheming undermines trust, and what matters is where the heart rests.",
    moves: [
      { title: "The mistaken idea", body: "Some think trust means stopping all work, stopping all planning, and lying on the ground like a rag. Ghazali says that is the idea of ignorant people, and it is forbidden by the religious law. The law praises those who trust, so trust can't be reached by doing what the law forbids." },
      { title: "Four reasons people act", body: "Everything a person deliberately does has one of four aims. They are getting something good they don't have (like earning), keeping something good they have (like saving), preventing a harm that hasn't happened (like guarding against thieves), or removing a harm that has happened (like treating an illness). Ghazali looks at trust in each of these." },
      { title: "Sure causes: eat the food", body: "Some causes work so reliably that the result always follows. If you are hungry, with food in front of you, and refuse to reach for it, saying, “I trust God,” that's madness, not trust. The same goes for not planting seeds and expecting crops. Here trust isn't in skipping the action. It is in knowing God made the food, the hand and the teeth — and resting your heart on Him, not on your hand, which could stop working at any moment." },
      { title: "Likely causes: take supplies", body: "Some causes usually work, but not always — like carrying food and water when crossing a desert. Taking supplies is the way of the early Muslims, and doesn't damage trust as long as your heart relies on God and not the supplies. Ghazali says Ibrahim al-Khawwas, famous for his trust, never travelled without a needle, scissors, a rope and a bucket, because there is no other way to get water out of a desert well." },
      { title: "The hermit on the mountain", body: "But cutting yourself off from all causes goes against God's wisdom. A hermit left the city to live on a mountain and said, “I won't ask anyone for anything until my Lord brings me my food.” After seven days he was close to death. God told him, “I won't feed you until you go back among people.” When he did, people brought him food. God told him: “I prefer to feed My servant by the hands of My servants than by the hand of My power.”" },
      { title: "Far-fetched schemes", body: "The third kind of cause is the far-fetched: endless clever schemes and tricks to squeeze out gain. Ghazali says relying on these takes a person out of trust entirely — and this is where most people are. He compares these to branding, charms and omens, which the Prophet named when describing those who trust. He didn't describe them as people who don't earn a living." },
      { title: "Abu Bakr goes to market", body: "The day after Abu Bakr became caliph, he picked up his cloth and went to the market to sell it. People objected. He said, “Don't keep me from my family. If I neglect them, I'll neglect everyone else even more.” Only when the Muslims agreed to pay him a basic salary did he stop. Ghazali says no one could claim Abu Bakr lacked trust. His trust was in his heart, not in quitting work." },
    ],
    closer: [
      { title: "The sign that you aren't relying on your money", body: "How can you tell whether you rely on your savings or skills? Ghazali's test: if your goods are stolen or your business fails, is your heart as calm after as before? “Whoever doesn't rest on something isn't shaken by losing it. Whoever is shaken by losing something was resting on it.”" },
      { title: "Two sayings to hold together", body: "Sahl al-Tustari said: “Whoever criticises earning a living criticises the Prophet's way. Whoever criticises not earning a living criticises belief in God's oneness.” And Abu Ja'far al-Haddad, who taught al-Junayd, kept his trust hidden for twenty years while working in the market, earning a coin a day and giving it all away before night." },
    ],
    distinction: ["Two people doing the same work", "Relying on the Creator", "The hands work, and the heart rests on the One who made the hands and what they achieve.", "Relying on the work", "The heart rests on the job, the savings or the plan — which is what removes trust."],
    misreading: "Don't conclude that any method of getting things is fine as long as you “trust”. Ghazali says far-fetched schemes and doubtful earnings go against trust, and that trust can't exist without being content with enough.",
    reflection: "Take something you worked hard on this week, and ask where your heart was resting while you did it.",
    audit: ["Where does my heart rest while I work?", "Which of my efforts are sure, likely, or far-fetched schemes?", "Would I be shaken if this plan failed?", "Have I ever called laziness “trust”?"],
    nodes: ["tawakkul", "means", "earning"],
    model: pair("The same act, two states", "The outward act settles nothing either way.", [["Trust intact", "The means is taken and the heart rests on the Creator of the means.", "support"], ["Trust displaced", "The heart rests on the arrangement, which is what removes the state.", "warning"]]),
  }),
  makeChapter({
    id: 9, shortTitle: "When others depend on you", formalTitle: "The trust of one who has others to provide for",
    overview: "What about someone with a family to feed? Ghazali says the rules change, because the risk would fall on people who didn't choose it. He also gives a beautiful argument about how God provides for every child.",
    thesis: "A person may take risks with their own hunger, but never with their family's — so someone with dependants must work, while their heart still trusts God.",
    moves: [
      { title: "What solitary trust requires", body: "Ghazali says someone alone can only truly trust God in the high way — without earning — if two things are true. They can go hungry for about a week without their heart panicking or looking to people. And they are at peace even with dying of hunger, if that is what God decides, seeing it as a gain in the next life." },
      { title: "You can't ask that of a family", body: "You can't make your family bear hunger, or expect them to see death by hunger as a blessing. So for someone with dependants, the only trust allowed is the trust of someone who works — like Abu Bakr going to the market. Leaving your family, or ignoring their needs, and calling it trust is forbidden, and you will be held responsible if they come to harm." },
      { title: "Your body is a dependant too", body: "Ghazali adds that your own body is also in your care. If you can't bear hunger without panic and your worship falls apart, you mustn't “trust” in that way either. Abu Turab saw a Sufi reach for a melon rind after three days without food and told him, “Sufism isn't for you — go to the market.”" },
      { title: "How God fed you before you could work", body: "Ghazali asks you to look at your own life. Before birth, you couldn't do anything, so God connected you to your mother through the umbilical cord. When you were born, He filled her heart with love so she would care for you whether she wanted to or not. You had no teeth, so He gave you milk. When you could eat solid food, He gave you teeth." },
      { title: "A thousand hearts instead of one", body: "Why would you suddenly start worrying about food once you grow up? As a child, one person — your mother — cared for you intensely. Now, Ghazali says, God has put mercy and kindness in the hearts of everyone around you, so that when they see someone in need, they feel it. Each one's care is weaker than a mother's, but there are a thousand of them. That is why orphans, in normal times, are looked after." },
      { title: "Only for the busy, not the lazy", body: "But what about a healthy adult who could earn? Ghazali agrees: if they are simply idle, they must work, and “trust” means nothing for them. Trust is a way to free yourself for God. If someone is truly devoted to worship and learning, people don't blame them for not earning, and usually bring them more than they need. The condition is not locking the door and running off to a mountain." },
      { title: "Enough, not luxury", body: "Ghazali is careful about what is promised. God hasn't promised fine food, soft clothes and fast horses. He has promised what keeps you alive. Most people who abandon trust do it because they want comfort, not survival. And the Quran promises: “Whoever is mindful of God, He will make a way out for them, and provide for them from where they never expected.”" },
    ],
    closer: [
      { title: "Why this matters beyond food", body: "This section shows that the rules of trust depend on whom the consequences fall on. Trust isn't only a private matter between you and God when other people's lives depend on your choices." },
      { title: "The same principle as repentance", body: "It matches what Book 31 said about repentance: turning to God doesn't cancel what you owe other people. A state of the heart between you and God doesn't cancel someone else's rights." },
    ],
    distinction: ["Two people choosing not to earn", "Alone", "The risk falls only on the one who chose it, and at the higher level it may be allowed.", "With dependants", "The risk falls on people who didn't choose it, and their rights still stand."],
    misreading: "Don't read this as saying people with families can't trust God. What is ruled out is abandoning the work — not the trust in the heart while doing it.",
    reflection: "Ask whose lives your choices are holding up, and whether any risk you are thinking about is really yours to take.",
    audit: ["Who depends on what I do?", "Whose risk am I really taking?", "Have I called neglecting others “trust”?", "Do I want enough, or do I want comfort?"],
    nodes: ["tawakkul", "dependents", "means"],
    model: chain("Whose risk", "The question governs what may be set aside.", [["Identify the dependent", "Who is actually held up by this arrangement.", "support"], ["Locate the risk", "Whether abandoning the means transfers it to them.", "balance"], ["Keep the means", "Where it does, the means is required rather than optional.", "support"], ["Keep the state", "The inward reliance remains fully available throughout.", "support"]]),
  }),
  makeChapter({
    id: 10, shortTitle: "The beggars at the palace", formalTitle: "The states of those who trust in their attachment to causes",
    overview: "Ghazali illustrates the different ways people relate to causes with a long parable: a king sends servants out with bread to a crowd of hungry people at his palace gate.",
    thesis: "People relate to causes in four ways — grabbing, taking extra, waiting in view, and hiding away — and the parable shows what each earns.",
    moves: [
      { title: "The king's bread", body: "A crowd of hungry people waits in a square outside a king's palace. The king sends out many servants with loaves. Some are told to give two loaves each, some one. They are told not to miss anyone. A herald announces: “Stay where you are. Don't grab my servants. They have been ordered to bring you your food.”" },
      { title: "The king's rules", body: "The herald goes on. Whoever grabs the servants, harasses them and takes two loaves will be followed after they leave and punished on a day the king keeps secret. Whoever doesn't harass them, and is content with one loaf handed to them calmly, will get a fine robe of honour on that day. Whoever stays put but takes two loaves gets neither punishment nor honour. And whoever is missed and goes hungry that night without complaining about the servants will be made the king's minister." },
      { title: "Group one: the grabbers", body: "The first group were ruled by their stomachs. They said, “Tomorrow is far off, and we're hungry now,” pushed the servants around and took two loaves. When the day of punishment came, they regretted it, but regret did no good." },
      { title: "Groups two and three", body: "The second group didn't grab the servants, but took two loaves because they were so hungry. They escaped punishment but got no honour. The third group said, “We'll sit where the servants can see us, so they don't miss us, and we'll be content with one loaf.” They won the robe of honour." },
      { title: "Group four: hiding in corners", body: "The fourth group hid in the corners of the square, out of sight. They said, “If the servants find us, we'll take one loaf. If they miss us, we'll bear the hunger without complaint, and maybe win the king's closeness.” But the servants found them in every corner, day after day. Then once, rarely, three were missed. Two complained, “We should have gone out where they could see us.” The third stayed silent until morning, and was made minister." },
      { title: "What the parable means", body: "The square is this life, and its gate is death. The secret day is the Day of Judgement. The servants are the causes, which God has put to work. The grabbers are those who push too hard at causes. Those sitting in view are people who live in towns, in mosques and communities, without chasing. Those hiding in corners are those who travel in wild places trusting God. And the promised post of minister is the reward of someone who dies hungry but content." },
      { title: "How many are like this", body: "Ghazali guesses that out of every hundred people, ninety cling to causes. Of the ten left, seven stay in towns and simply make themselves available. Three go out into the wilderness, two of those complain, and one wins nearness to God. And that, he says, was in earlier times. Now, someone who gives up causes in that way is less than one in ten thousand." },
    ],
    closer: [
      { title: "The food finds you anyway", body: "The most striking detail is that the servants find the people hiding in corners “in every corner”. Ghazali's point is that provision follows people. It is rare for someone to be truly missed. Al-Junayd told people looking for their provision: “If you know where it is, go and look for it.”" },
      { title: "Testing trust is doubt", body: "Some people told al-Junayd, “We'll shut ourselves in and trust God, and see what happens.” He said, “Trusting as an experiment is doubt.” They asked what they should do. He said, “Give up scheming.” Trust can't be a test to see whether God will come through." },
    ],
    distinction: ["Two relations to a cause", "Used without leaning on it", "The cause is used, and the heart doesn't rest on it — the first level, which is enough.", "Not reached for at all", "The cause itself is left — a higher level, and asked of no one."],
    misreading: "Don't copy the fourth group by dropping causes you actually depend on. Ghazali says that level is extremely rare, and the third group — sitting calmly in view and taking one loaf — is also honoured.",
    reflection: "Notice which group you most often act like when you are worried about getting what you need.",
    audit: ["Do I grab, take extra, wait calmly, or hide?", "Am I content with one loaf?", "Have I ever treated trust as an experiment?", "Would my composure survive being missed?"],
    nodes: ["tawakkul", "means", "three-stations"],
    model: pair("Where the difference lies", "Not in the act but in the resting place.", [["The act", "Identical across stations, which is why it proves nothing.", "balance"], ["The resting place", "Where the heart actually sits, which is what the stations grade.", "support"]]),
  }),
  makeChapter({
    id: 11, shortTitle: "Saving for later", formalTitle: "That storing with a heart free of what is stored does not annul trust",
    overview: "Saving things for the future looks like the opposite of trust. Ghazali says it doesn't have to be. What matters is how long your hopes stretch, how strong your heart is, and whether you have people depending on you.",
    thesis: "Saving doesn't cancel trust when the heart isn't attached to what is saved — the less you store, the higher the level, but a weaker heart or a family can make saving the better choice.",
    moves: [
      { title: "Three ways to handle money", body: "When money comes to you, Ghazali says there are three ways to handle it. First: take what you need now — food, clothes, a simple home — and give the rest away, keeping only what you're holding for someone in need. That is the highest level of trust. Second, the opposite: store enough for a year or more. That is outside trust. Third: store for forty days or less — which scholars disagreed about." },
      { title: "The ant, the mouse and the human", body: "People used to say only three creatures store food: the mouse, the ant and the human. Sahl said storing even forty days takes you out of trust. Ibrahim al-Khawwas said forty days is fine but more isn't. Abu Talib al-Makki said even more than forty is fine." },
      { title: "It depends on your hopes", body: "Ghazali says arguing about the exact number misses the point. What prevents storing is having short hopes — not assuming you'll be around for a long time. Everyone expects to live at least a little while. But someone who plans a month ahead is closer to the goal than someone who plans a year ahead. There are endless levels in between." },
      { title: "The man with the summer cloak", body: "A poor Companion died, and the Prophet said he would rise on the Day of Judgement with his face shining like the full moon. “And if not for one habit, his face would have shone like the midday sun.” He fasted, prayed and remembered God a lot. But when winter came, he stored his summer cloak for the summer, and when summer came, he stored his winter cloak for the winter." },
      { title: "For a weak heart, saving is better", body: "But Ghazali doesn't say everyone should stop saving. If not having savings makes your heart so restless that you can't worship or think straight, then saving is better for you — even owning land whose income covers your needs. “Some people are distracted by having money, and some by not having it.” The thing to avoid is whatever distracts you from God. Money in itself is not the enemy." },
      { title: "The Prophet stored for his family", body: "Someone with a family doesn't leave trust by storing a year's food for them, to support their weakness and calm their hearts. The Prophet himself stored a year's food for his family. But for himself, he told Bilal, who had saved some bread to break his fast: “Spend, Bilal, and don't fear poverty from the Lord of the Throne.”" },
      { title: "He did both, to teach both", body: "Why did the Prophet do both? Ghazali says he wasn't weak, and storing wouldn't have harmed his trust. He didn't store for himself, to teach the strong. He stored for his family, to give permission to the weak. That way, weak people wouldn't give up on doing good just because they can't reach the highest level. God loves people to use His permissions, just as He loves them to keep His firmer rules." },
    ],
    closer: [
      { title: "Fath takes the leftovers", body: "Bishr al-Hafi once had a guest he rose to greet, which he never did for anyone. He sent his student to buy the best food. After they ate, the guest wrapped up the leftovers and took them away. The student was surprised. Bishr said, “That was our brother Fath al-Mawsili. He wanted to teach us that when trust is real, saving does it no harm.”" },
      { title: "The real test", body: "The question isn't how much is in the cupboard, but what losing it would do to you. Savings whose loss would shake you to pieces were carrying a promise that no created thing can keep." },
    ],
    distinction: ["Two kinds of savings", "Held loosely", "The heart isn't attached to it, and losing it wouldn't move your trust.", "Held tightly", "It fills your thoughts, and your trust has moved into it."],
    misreading: "Don't read this as permission to pile up money without limit, or as a rule that saving is always wrong. Ghazali ties it to short hopes, to the strength of your heart, and to who depends on you.",
    reflection: "Ask what losing your savings would actually do to you. That answer is this section's test.",
    audit: ["What would losing this do to me?", "Does it take up my thoughts?", "Am I saving for a real need, or out of fear?", "How far ahead do my hopes stretch?"],
    nodes: ["tawakkul", "storing", "means"],
    model: pair("The test for a store", "Quantity is not what decides it.", [["Empty of it", "The store exists and its loss would not displace the reliance.", "support"], ["Occupied by it", "The store has become where the heart rests, which is the failure.", "warning"]]),
  }),
  makeChapter({
    id: 12, shortTitle: "Locking the door", formalTitle: "The manners of those who trust when their goods are stolen",
    overview: "Protecting yourself and your things doesn't cancel trust. Ghazali explains how to lock the door while trusting God — and how someone who trusts should react when something is stolen.",
    thesis: "Trust means taking sensible precautions while your heart relies on God — and when something is still taken, meeting it with contentment, forgiveness and even concern for the thief.",
    moves: [
      { title: "Tie your camel", body: "A Bedouin let his camel wander loose and said, “I trust in God.” The Prophet told him, “Tie it, and trust God.” Ghazali says trust doesn't mean sleeping where wild animals roam, in the path of a flood, or under a crumbling wall. The Quran tells believers to take precautions, and the Prophet hid in a cave from his enemies. Sure and likely protections are part of trust. Only far-fetched ones go against it." },
      { title: "Harm from people is different", body: "There is one exception. If harm comes from a person and you could either bear it patiently or hit back, trust means patience. The Quran says, “Bear patiently what they say, and rely on God.” But putting up with snakes, scorpions and wild animals has no benefit, so there is nothing trusting about not dealing with them." },
      { title: "Tame the dog inside first", body: "Some stories tell of saints who let lions rest a paw on their shoulders, or even rode them. Ghazali says: don't copy that. It is a rare gift, not a condition of trust. And if you want a sign that you are near it, look inside. You have a dog in your own skin called anger. If you can't make that dog obey you, don't dream of taming the dogs of the desert." },
      { title: "How the one who locks the door still trusts", body: "When you lock your door, tie your camel or take precautions, how are you still trusting God? Through knowledge and through your heart. The knowledge: many locked doors don't stop thieves, many tied camels still die or escape, and many armed people are still beaten. The heart: you are content with whatever God decides about your home and your belongings." },
      { title: "A prayer when you leave", body: "Ghazali suggests what the heart might say: “O God, if You let someone take what's in my house, let it be for Your sake, and I accept Your decision. I don't know whether it was a gift or a loan, or whether it was meant for me or someone else. I didn't lock the door to escape Your decree, but to follow the way You've arranged things.” If you come back and find everything there, treat it as a new gift." },
      { title: "The test when it's gone", body: "If you find your things stolen, look at your heart. If you are content — even glad, knowing God took it to give you more in the next life — your trust was real. If your heart hurts but you stay patient, you have patience, not yet trust. If you complain loudly and search frantically, you have learned something humbling about yourself. Ghazali says, don't believe your ego's claims so easily." },
      { title: "Good manners with a thief", body: "Ghazali gives the manners of someone who trusts. Lock the door, but don't go overboard with extra locks and guards. Malik ibn Dinar only tied his door with string, “because of the dogs.” Don't leave valuables lying around to tempt thieves into sin. As you leave, intend that anything taken is a gift to the taker, so it becomes charity and saves them from eating stolen goods." },
    ],
    closer: [
      { title: "Don't curse the thief", body: "Ghazali says the least you should do is not pray against the thief. When al-Rabi' ibn Khuthaym's expensive horse was stolen while he prayed, he saw it happen but didn't break his prayer. When visitors started cursing the thief, he said, “Don't. Say something good. I've made the horse a charity for him.” Someone else said, “I don't want to help the devil against him.”" },
      { title: "Crying for the thief", body: "Ali, son of al-Fudayl, had money stolen while circling the Ka'ba, and his father found him crying. “Are you crying over the coins?” “No, by God. I'm crying for that poor man who will be questioned on the Day of Judgement and have no excuse.” Ghazali says the right response is sadness that a Muslim has sinned, and gratitude that God made you the one wronged, not the wrongdoer." },
    ],
    distinction: ["Two responses to a theft", "Acting without being shaken", "Sensible steps are taken, and the heart stays where it was resting.", "Being knocked loose", "The loss shows that trust had moved into the thing that was lost."],
    misreading: "Don't read this as saying you must not care about loss, report a crime, or protect your rights. Ghazali allows sensible steps. He is examining where your heart was resting.",
    reflection: "Remember your last real loss. What did your reaction reveal about where your trust had settled?",
    audit: ["What did my last loss reveal about me?", "Did I take sensible steps, or was I consumed?", "Have I prayed against someone who wronged me?", "Have I tamed the dog inside me?"],
    nodes: ["tawakkul", "storing"],
    model: chain("What a loss reveals", "The response is not chosen in advance, which is what makes it evidence.", [["The loss occurs", "What was stored is taken.", "balance"], ["Steps are taken", "Recovery is permitted on the same principle as taking means.", "support"], ["The inmost self", "Whether it stirred is the criterion, and it is not decided by the steps.", "balance"]]),
  }),
  makeChapter({
    id: 13, shortTitle: "Medicine and trust", formalTitle: "That leaving medical treatment is praised in some conditions",
    overview: "Does using medicine go against trust? No, Ghazali says — the Prophet used it and told people to use it. But many great early Muslims chose not to be treated, and Ghazali praises them too. He explains how both can be right by listing the reasons they had.",
    thesis: "Using medicine doesn't go against trust, and leaving it isn't wrong either: for some people, in some states and for some reasons, leaving treatment is the better choice.",
    moves: [
      { title: "Three kinds of remedy", body: "Things that remove harm come in three kinds. Sure ones, like water for thirst and bread for hunger. Leaving these isn't trust at all — leaving them when you fear death is forbidden. Likely ones, like the treatments doctors use. Using them doesn't go against trust, and leaving them isn't forbidden; in some states and for some people, leaving them is better. And far-fetched ones, like branding with fire and charms. Leaving these is part of trust, because that is how the Prophet described those who trust God." },
      { title: "The Prophet commanded it", body: "The Prophet said, “There is no disease without a cure, known to some and unknown to others — except death.” He said, “Seek treatment, servants of God, for God created both the disease and the cure.” When asked whether medicine can push back God's decree, he said, “It is part of God's decree.” He was treated himself, and told several Companions to be treated." },
      { title: "Moses refuses treatment", body: "Ghazali tells a story. Moses fell ill, and people told him of a well-known remedy. He said, “I won't take anything. God will heal me without it.” His illness went on. God told him, “By My might, I won't heal you until you take what they told you.” He took it and recovered. When he felt uneasy about this, God told him: “Did you want to cancel My wisdom by relying on Me instead of the medicines I filled with benefits?”" },
      { title: "What doctors are for", body: "Moses once asked God, “Where do disease and cure come from?” God said, “From Me.” “Then what do doctors do?” “They earn their living and comfort My servants, until My cure or My decree arrives.” So, Ghazali says, you can take medicine while your heart looks to the One who put the cure in it, not to the doctor or the pill." },
      { title: "Great people who said no", body: "Still, many great early Muslims left treatment. When people offered to call a doctor for Abu Bakr, he said, “The Doctor has seen me, and He said: I do whatever I will.” Abu al-Darda', when ill, was asked what hurt. “My sins.” What did he want? “My Lord's forgiveness.” Should they call a doctor? “The Doctor made me ill.” Abu Dharr had sore eyes and was told to treat them. He said, “I'm busy with something else.”" },
      { title: "Rabi' and Imam Ahmad", body: "Al-Rabi' ibn Khuthaym was paralysed and was told to get treatment. He said, “I thought about it. Then I remembered the ancient peoples of 'Ad and Thamud. They had doctors too, and both the doctors and their patients died.” Imam Ahmad ibn Hanbal said he liked those who follow the path of trust to leave medicine, and not even tell a doctor about their illness if asked. Sahl said trust is real when harm comes to your body and loss to your money, and you don't turn to look at it, because you are busy watching God's care over you." },
      { title: "Reason one: they knew their time had come", body: "So how do these people fit with the Prophet's example? Ghazali says you only see it once you list their reasons. The first: the sick person has been shown that their life is over and no medicine will help — through a true dream, a strong sense, or clear insight. Abu Bakr may have been like this. Before he died he told his daughter Aisha about her “two sisters”, though she had only one. His wife was pregnant, and she later had a girl. He had been shown it." },
      { title: "Reason two: too busy to notice", body: "The second: the sick person is so taken up with fear of how they will end, and with God watching them, that they forget the pain. Abu Dharr's “I'm busy” and Abu al-Darda's “My sins” are like this. Picture someone being taken to a king to be executed. Offer him food and he says, “I'm too busy to feel hungry.” He isn't denying that food helps. Sahl was once asked what feeds the body. He said, “Leave the body to the One who made it. When something made is broken, you send it back to its maker.”" },
      { title: "Reason three: a long illness and a doubtful cure", body: "The third: the illness is long-lasting, and the medicine for it is so uncertain that it is like branding and charms. That is what al-Rabi' meant: the doctors died along with the patients. Sometimes a medicine really is doubtful. Sometimes it only seems so to a person who knows little about medicine. An experienced doctor trusts medicines far more than others do, because trust follows experience. Ghazali says this is the reason most worshippers who left treatment had." },
      { title: "Reason four: the reward of patience", body: "The fourth: the person wants to keep the illness for the reward of bearing it well, or to test their own patience. The Prophet said, “We prophets are tested hardest, then the best, then the next best.” God tests a person with trouble as you test gold: some come out pure, some less so, some burnt black. Illness also wipes away sins. When the Prophet said fever removes sins, Zayd ibn Thabit asked God that he never be without fever, and it never left him until he died. When Moses saw a man suffering and asked God to have mercy on him, God said, “How can I have mercy on him in the very thing I am using to have mercy on him?”" },
      { title: "Reason five: fear of what health does", body: "The last: the person feels that long health is making them careless, proud and full of plans for later. Health, Ghazali says, gives strength to desire, and desire pulls toward sin — or at least toward wasting time on comfort. People said Pharaoh claimed to be God because he lived four hundred years without a headache or a fever. One day of migraine would have kept him too busy for that. Fever, it was said, is death's messenger, and illness is a reminder of death that cuts through “later”." },
    ],
    closer: [
      { title: "Worried by a year without trouble", body: "Because of this, the early Muslims felt uneasy when a year went by and they had lost nothing in body or wealth. They said a believer isn't left for forty days without some fright or trouble. It is said that when a person falls ill twice and still doesn't repent, the angel of death tells him, “Careless one, I sent you messenger after messenger, and you didn't answer.” So these people left treatment because they saw more good for themselves in the illness — not because they thought treatment was a flaw. How could it be a flaw, when the Prophet did it?" },
      { title: "Why branding is different", body: "Someone might ask: isn't branding also a treatment that clearly works? Ghazali says no. If it were, it wouldn't be missing from so many lands; it was the custom of only some peoples. And it burns the body when there is always another treatment that doesn't burn. That is why the Prophet forbade branding, and did not forbid charms in the same way." },
    ],
    distinction: ["Two ways to leave treatment", "For a reason", "Knowing the end has come, being taken up with God, doubting the cure, wanting the reward, or fearing what health does — which Ghazali praises.", "Because medicine is a flaw", "Treating it as a failure of trust — which the Prophet's own practice rules out."],
    misreading: "Don't think Ghazali is ranking one choice above the other for everyone. He praises the Prophet, who was treated, and the great people who weren't. What makes each right is the person's state and reason.",
    reflection: "Notice that Ghazali doesn't explain away either side. He keeps the Prophet's practice and the choices of Abu Bakr and Abu al-Darda', and looks for the reasons that make both true.",
    audit: ["Is this remedy sure, likely, or far-fetched?", "When I take medicine, where does my heart look?", "Has good health made me careless or proud?", "What would my reason be if I chose to bear something patiently?"],
    nodes: ["tawakkul", "treatment", "causes"],
    model: pair("Two right choices", "Ghazali lists the reasons that make leaving treatment praiseworthy.", [["Taking likely remedies", "Doesn't go against trust — the Prophet did it and commanded it.", "support"], ["Leaving likely remedies", "Can be better for some people: those shown their end, absorbed in God, doubting the cure, seeking reward, or fearing health's effects.", "balance"]]),
  }),
  makeChapter({
    id: 14, shortTitle: "Against never using medicine", formalTitle: "A refutation of those who say leaving treatment is better in every case",
    overview: "Some people claimed that refusing treatment is always better. Ghazali spends a whole section showing why that is wrong, using a simple chain of examples and a famous decision by Umar during a plague.",
    thesis: "Refusing treatment is not always better: if it were, you would also have to refuse water, bread and warm clothes — and Umar showed that avoiding harm is running from one thing God decides to another.",
    moves: [
      { title: "The claim", body: "Someone might say: “The Prophet used medicine only to set an example for weaker people. For strong people, trust means refusing all treatment.” Ghazali answers by following that idea to where it leads." },
      { title: "Where the idea leads", body: "If trust means refusing treatment, then you must also refuse to let out blood when it is dangerously built up. If that too, then you mustn't brush off a scorpion stinging you — since bad blood stings inside and a scorpion stings outside. If that too, then you mustn't cure the sting of thirst with water, hunger with bread, or cold with a coat. And nobody says that." },
      { title: "All causes are the same kind", body: "Ghazali's point is that there is no real difference between these steps. They are all causes that God, the Causer of causes, has arranged and made His way in the world. Putting out a fire in your house isn't a lack of trust. Neither is taking medicine." },
      { title: "Umar and the plague", body: "Umar led the Muslims toward Syria, and near the border heard that a terrible plague had broken out there. People split into two groups. Some said, “Let's not walk into the plague and throw ourselves into destruction.” Others said, “Let's go in, trusting God. We shouldn't run from God's decree.” They asked Umar, and he decided: “We go back.”" },
      { title: "From decree to decree", body: "Those who disagreed asked, “Are you running away from what God has decreed?” Umar said, “Yes — we run from God's decree to God's decree.” He gave a picture: “If you had sheep and came to a valley with a green slope and a dry slope, wouldn't you be grazing them by God's decree whichever side you chose?” Then Abd al-Rahman ibn Awf arrived and reported that the Prophet had said: “If you hear of plague in a land, don't go into it. And if it breaks out where you are, don't flee from it.”" },
      { title: "Why the Prophet didn't refuse", body: "If there is some good in refusing treatment in some cases, why didn't the Prophet do it? Ghazali says those reasons — too many sins, fear of arrogance, needing a reminder of death, weak understanding of medicine — belong to people below the Prophet's level. For him, having causes or not having them made no difference to his heart. So he used medicine, following God's way and making it easy for his community." },
      { title: "The real danger in medicine", body: "Ghazali says medicine only harms trust in two ways: if you see the medicine itself as the healer, rather than God who made it, or if you want health in order to use it for sin. A believer doesn't normally do either — just as nobody thinks water quenches thirst on its own. So treatment is like earning a living: its value depends on what you use it for." },
      { title: "Ghazali's conclusion", body: "So, Ghazali says, leaving treatment is sometimes better and treatment is sometimes better. It changes with the person's state, who they are and what they intend. Neither taking it nor leaving it is a condition of trust — except leaving far-fetched things like branding and charms, which trust does require." },
    ],
    closer: [
      { title: "Why it comes straight after the permission", body: "Ghazali put this section right after the one allowing some people to leave treatment. Putting the permission and its limit side by side makes it very hard to carry away one without the other." },
      { title: "Where the mistake comes from", body: "Ghazali says people who only look at the surface of reports find them contradicting each other, and many worshippers and ascetics make mistakes like this. That, he says, is exactly why real knowledge is so valuable." },
    ],
    distinction: ["Two ways to hold the permission", "With its limit", "Likely remedies may be left by particular people, in particular states, for particular reasons.", "As a general rule", "All treatment is refused as a “higher” way — which this section is written against."],
    misreading: "Don't read the previous section without this one. Ghazali put them together on purpose, and separating them produces exactly the view he rejects here.",
    reflection: "Notice how much more appealing a simple rule (“never use medicine”) can be than a careful one, and ask why.",
    audit: ["Have I stretched a permission beyond its limit?", "Do I prefer simple rules to careful thinking?", "Where am I judging someone's faith by one visible act?", "Do I see a remedy as the healer, or as a cause God made?"],
    nodes: ["tawakkul", "treatment", "means"],
    model: chain("How a permission becomes an error", "The steps are easy to take and hard to notice.", [["A bounded grant", "Speculative remedies may be left in some conditions.", "balance"], ["The bound is dropped", "The condition is forgotten and the grant is remembered.", "warning"], ["An outward rule", "The state is replaced by a visible act as its evidence.", "warning"], ["The criterion restored", "Where the heart rests, which the act never settled.", "support"]]),
  }),
  makeChapter({
    id: 15, shortTitle: "Telling people you're ill", formalTitle: "The states of those who trust in disclosing or concealing illness",
    overview: "The book ends on a small, practical question: should someone who trusts God keep their illness to themselves or tell people? Ghazali says keeping it quiet is a treasure, but telling is fine for the right reasons.",
    thesis: "Keeping your hardship private is a treasure of goodness, but telling others is fine when the purpose is right — getting treatment, teaching patience, or admitting your need of God.",
    moves: [
      { title: "Keeping it quiet is a treasure", body: "Ghazali says hiding illness, poverty and other hardships is one of “the treasures of goodness” and a high level. Being content with God's decision and patient with His test is something between you and God. Keeping it private keeps it safe from the problems that come with showing it." },
      { title: "But telling can be fine", body: "Still, there is no harm in telling people if your intention and purpose are sound. Ghazali names three good purposes. The first is getting treatment: you need to tell the doctor. But you tell it as a report, not as a complaint." },
      { title: "Ahmad and Bishr", body: "Bishr al-Hafi used to describe his pains to his doctor. Imam Ahmad ibn Hanbal would tell people about illnesses he was suffering and say, “I'm only describing God's power at work in me.” The words were the same as a complaint, but their purpose was completely different." },
      { title: "To teach patience and thanks", body: "The second purpose is teaching. Someone respected, who others follow, may mention their illness so people can learn from how they bear it — or even thank God for it, as if talking about a blessing. Al-Hasan al-Basri said, “If a sick person praises God and thanks Him, and then mentions their pain, that isn't complaining.”" },
      { title: "To show you need God", body: "The third purpose is showing your weakness and need of God. This suits someone known for strength. When Ali was ill, someone asked how he was, and he said, “Bad.” People looked at each other, uncomfortable, thinking it sounded like complaining. He explained: “Should I act tough in front of God?” He wanted to show his need of God." },
      { title: "Why no simple rule works", body: "The question is harder than it looks. Telling people can look like complaining. Keeping quiet can look like showing off how patient you are. Someone who decides only by how it looks will fall into one mistake or the other. So the answer has to come from the purpose, not the act." },
      { title: "Complaint versus report", body: "The fault, when there is one, lies in what the words are being used to do: to win sympathy, to show how much you are enduring, or to make complaining a habit. The same sentence — “I'm ill” — can seek treatment, explain an absence, ask for help, or fish for pity." },
    ],
    closer: [
      { title: "Why the book ends here", body: "Because the smallest case shows the method at work. If you can decide whether to mention a fever by looking at your heart, you can decide the big questions at the start of the book the same way." },
      { title: "What you take away", body: "Not a rule about using or avoiding causes, but a place to look. Every question in the second half was answered by asking where the heart was resting, not by asking what the hand had done." },
    ],
    distinction: ["Two ways of telling people the same illness", "Reporting", "Said for a good purpose, such as treatment, teaching, or admitting need of God — not a complaint.", "Complaining", "Said to get a particular reaction — which is where the fault lies."],
    misreading: "Don't read the praise of keeping quiet as a rule that you must hide real illness. Ghazali clearly allows telling people for good reasons — and telling a doctor is one of them.",
    reflection: "Before mentioning a difficulty, ask what you want the listener to do with it. The answer usually settles it.",
    audit: ["What do I want from telling this?", "Can the person I'm telling actually help?", "Am I reporting, or fishing for a reaction?", "Am I hiding things to look patient?"],
    nodes: ["tawakkul", "disclosure"],
    model: pair("The last application of one criterion", "The method that answered every case in Part Two.", [["A purpose", "Told to someone who can act, which makes it a report.", "support"], ["A response", "Told to be received in a particular way, which is where the fault is.", "warning"]]),
  }),
];

const book35Deepening: Partial<Record<number, { title: string; body: string }>> = {};

export const book35Chapters: Chapter[] = book35Base.map((chapter) => {
  const extra = book35Deepening[chapter.id];
  if (!extra || !chapter.deep) return chapter;
  return { ...chapter, deep: { ...chapter.deep, closeReading: [...(chapter.deep.closeReading ?? []), extra] } };
});

